import org.jsoup.nodes.Document;
import org.jsoup.nodes.TextNode;
import org.junit.Test;
import static org.junit.Assert.*;

public class TextNodeTest {

    @Test
    public void nodeNameTest() {
        TextNode node = new TextNode("test");
        assertEquals("#text", node.nodeName());
    }

    @Test
    public void textTest() {
        TextNode node = new TextNode("test");
        assertEquals("test", node.text());
    }

    @Test
    public void textAssignTest() {
        TextNode node = new TextNode("test");
        node.text("new text");
        assertEquals("new text", node.text());
    }

    @Test
    public void getWholeTextTest() {
        TextNode node = new TextNode("test");
        assertEquals("test", node.getWholeText());
    }

   @Test
    public void isBlankTest() {
        TextNode node = new TextNode("");
        assertTrue(node.isBlank());
    }

    @Test
    public void splitTextTest() {
        TextNode node = new TextNode("test");
        TextNode splitNode = node.splitText(2);
        assertEquals("st", splitNode.getWholeText());
    }

    @Test
    public void toStringTest() {
        TextNode node = new TextNode("test");
        assertTrue(node.toString().contains("test"));
    }

    @Test
    public void cloneTest() {
        TextNode node = new TextNode("test");
        TextNode clonedNode = node.clone();
        assertEquals("test", clonedNode.text());
    }

    @Test
    public void createFromEncodedTest() {
        TextNode node = TextNode.createFromEncoded("test");
        assertNotNull(node);
    }

    @Test
    public void normaliseWhitespaceTest() {
        String text = "   test  ";
        String normalisedText = TextNode.normaliseWhitespace(text);
        assertEquals(" test ", normalisedText);
    }

    @Test
    public void stripLeadingWhitespaceTest() {
        String text = "   test";
        String strippedText = TextNode.stripLeadingWhitespace(text);
        assertEquals("test", strippedText);
    }

    @Test
    public void lastCharIsWhitespaceTest() {
        StringBuilder text = new StringBuilder("test ");
        assertTrue(TextNode.lastCharIsWhitespace(text));
    }

    @Test
    public void outerHtmlHeadTest() {
        TextNode node = new TextNode("test");
        Appendable accum = new StringBuffer();
        Document.OutputSettings out = new Document("").outputSettings();
        node.outerHtmlHead(accum, 0, out);
        assertEquals("test", accum.toString());
    }

    @Test
    public void outerHtmlTailTest() {
        TextNode node = new TextNode("test");
        Appendable accum = new StringBuffer();
        Document.OutputSettings out = new Document("").outputSettings();
        node.outerHtmlTail(accum, 0, out);
        assertEquals("", accum.toString());
    }
}
